package rules

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
)

// specJSON is the standard's own text (per-rule why / check / fix / tool, the
// profile and level tables, the family titles), generated by standard/build_pdf.py
// from the same RULES source as the PDF, RULES.md and manifest.yaml. It is
// embedded so the binary serves it with no network and no file on disk.
//
//go:embed spec.json
var specJSON []byte

// Spec is the parsed form of spec.json.
type Spec struct {
	ID       string        `json:"id"`
	Title    string        `json:"title"`
	Version  string        `json:"version"`
	Date     string        `json:"date"`
	Profiles []SpecProfile `json:"profiles"`
	Levels   []SpecLevel   `json:"levels"`
	Families []SpecFamily  `json:"families"`
}

// SpecProfile is one row of the standard's profile table.
type SpecProfile struct {
	Name  string `json:"name"`
	Label string `json:"label"`
	For   string `json:"for"`
	Adds  string `json:"adds"`
}

// SpecLevel is one row of the standard's conformance-level table.
type SpecLevel struct {
	Name    string `json:"name"`
	Label   string `json:"label"`
	Meaning string `json:"meaning"`
	Control string `json:"control"`
	Typical string `json:"typical"`
}

// SpecFamily is one section of the standard (e.g. §2 AG-NET).
type SpecFamily struct {
	Section string     `json:"section"`
	Prefix  string     `json:"prefix"`
	Title   string     `json:"title"`
	Rules   []SpecRule `json:"rules"`
}

// SpecRule is the normative text of one rule, verbatim from the standard
// (HTML markup removed, inline code kept as backticks).
type SpecRule struct {
	ID        string `json:"id"`
	Title     string `json:"title"`
	Applies   string `json:"applies"`
	CheckType string `json:"check_type"`
	Why       string `json:"why"`
	Check     string `json:"check"`
	Fix       string `json:"fix"`
	Tool      string `json:"tool"`
}

var loadSpec = sync.OnceValues(func() (*Spec, error) {
	var s Spec
	if err := json.Unmarshal(specJSON, &s); err != nil {
		return nil, fmt.Errorf("embedded spec.json: %w", err)
	}
	return &s, nil
})

// StandardSpec returns the embedded standard text. The error is non-nil only if
// the embedded file is malformed, which spec_test.go rules out at build time.
func StandardSpec() (*Spec, error) { return loadSpec() }

// SpecFor returns the standard's text for rule id and the family it belongs to.
// ok is false when the standard holds no text for the id.
func SpecFor(id string) (rule SpecRule, fam SpecFamily, ok bool) {
	s, err := loadSpec()
	if err != nil {
		return SpecRule{}, SpecFamily{}, false
	}
	for _, f := range s.Families {
		for _, r := range f.Rules {
			if r.ID == id {
				return r, f, true
			}
		}
	}
	return SpecRule{}, SpecFamily{}, false
}

// Lookup returns the registry rule whose id matches id case-insensitively.
func Lookup(id string) (Rule, bool) {
	id = strings.TrimSpace(id)
	for _, r := range All() {
		if strings.EqualFold(r.ID, id) {
			return r, true
		}
	}
	return Rule{}, false
}

// String names a level mode with the vocabulary of manifest.yaml.
func (m LevelMode) String() string {
	switch m {
	case LevelRequired:
		return "required"
	case LevelAdvisory:
		return "advisory"
	case LevelOutOfScope:
		return "out_of_scope"
	case LevelForbidden:
		return "forbidden"
	}
	return fmt.Sprintf("LevelMode(%d)", uint8(m))
}
